DROP POLICY IF EXISTS product_batch_certifications_authenticated_read ON public.product_batch_certifications;
CREATE POLICY product_batch_certifications_authenticated_read ON public.product_batch_certifications
  FOR SELECT
  TO authenticated
  USING ((EXISTS ( SELECT 1
   FROM (product_batches batch
     LEFT JOIN producers producer ON ((producer.id = batch.producer_id)))
  WHERE ((batch.id = product_batch_certifications.batch_id) AND ((batch.status = 'released'::text) OR (producer.owner_user_id = ( SELECT auth.uid() AS uid)) OR ( SELECT private.is_admin() AS is_admin))))));

DROP POLICY IF EXISTS product_batch_certifications_public_read ON public.product_batch_certifications;
CREATE POLICY product_batch_certifications_public_read ON public.product_batch_certifications
  FOR SELECT
  TO anon
  USING ((EXISTS ( SELECT 1
   FROM (product_batches batch
     JOIN product_certifications certification ON ((certification.id = product_batch_certifications.certification_id)))
  WHERE ((batch.id = product_batch_certifications.batch_id) AND (batch.status = 'released'::text) AND (certification.product_id = batch.product_id) AND (certification.status = 'valid'::text) AND ((certification.expires_at IS NULL) OR (certification.expires_at >= CURRENT_DATE))))));

