DROP POLICY IF EXISTS reviews_insert_verified_purchase ON public.reviews;
CREATE POLICY reviews_insert_verified_purchase ON public.reviews
  FOR INSERT
  TO authenticated
  WITH CHECK (((user_id = ( SELECT auth.uid() AS uid)) AND (status = 'pending'::text) AND (is_verified_purchase = true) AND (EXISTS ( SELECT 1
   FROM (order_items purchased_item
     JOIN orders customer_order ON ((customer_order.id = purchased_item.order_id)))
  WHERE ((purchased_item.id = reviews.order_item_id) AND (purchased_item.product_id = reviews.product_id) AND (customer_order.user_id = ( SELECT auth.uid() AS uid)) AND (customer_order.status = ANY (ARRAY['delivered'::text, 'completed'::text])))))));

